    public static function operation(string $operation,array $messages):string
    {
        $source=match($operation){
            'create'=>'Lokaler E-Bilanz-Entwurf angelegt','save'=>'Angaben gespeichert','generate'=>'XML lokal vorbereitet',
            'validate'=>'Lokale Prüfung abgeschlossen','approve'=>'Vorstandsfreigabe gespeichert','revision'=>'Abgabeart gespeichert',
            'adjust'=>'Steuerwerte berichtigt','carry'=>'Vorjahreswerte übernommen','asset'=>'Anlagenplan geprüft',
            'capital'=>'Kapitalbewegungen geprüft','partnership'=>'Beteiligungsnachweis verbunden','own-intangible'=>'Entwicklungsnachweis verbunden',
            'pool-original'=>'Sammelpostennachweis verbunden','pension-offsets'=>'Pensionsnachweis verbunden',
            'financial-reserve'=>'Rücklagennachweis verbunden','financial-reserve-withdraw'=>'Rücklagenentwurf zurückgenommen',
            'equalization'=>'Ausgleichsposten geprüft',default=>'Steuerwahl verbunden',
        };
        return self::text($source,$messages);
    }
    public static function key(string $source):string{return 'balance_filing_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as $source=>$text)$out[self::key($source)]=$en?$text:$source;return $out;}
    public static function text(string $source,array $messages):string
    {
        if(isset($messages[self::key($source)]))return $messages[self::key($source)];
        foreach(['Noch abzustimmende Rechnungen insgesamt: ','Noch abzustimmende Bankumsätze insgesamt: ','Rechnung noch nicht übernommen: ']as$sourcePrefix)if(str_starts_with($source,$sourcePrefix)&&isset($messages[self::key($sourcePrefix)]))return $messages[self::key($sourcePrefix)].substr($source,strlen($sourcePrefix));
        $bankTemplate='Bankumsatz vom {date} noch nicht übernommen.';
        if(preg_match('/\A' . 'Bankumsatz vom ([0-9]{4}-[0-9]{2}-[0-9]{2}) noch nicht übernommen\.\z/D',$source,$bankDate)&&isset($messages[self::key($bankTemplate)]))return str_replace('{date}',implode('.',array_reverse(explode('-',$bankDate[1]))),$messages[self::key($bankTemplate)]);
        $prefix='Steuerliche Bilanzwerte sind nicht abgestimmt: ';
        if(str_starts_with($source,$prefix)&&isset($messages[self::key($prefix)]))return $messages[self::key($prefix)].substr($source,strlen($prefix));
        return TaxFilingMessages::text($source,$messages);
    }
